#include <iostream>
#include <string>
#include <cctype>
#include <vector>
using namespace std;

enum class TokenType { NUMBER, OPERATOR, END };
struct Token { TokenType type; string value; };

vector<Token> tokenize(const string& input) {
    vector<Token> tokens;
    for (size_t i = 0; i < input.size(); i++) {
        if (isspace(input[i])) continue;
        if (isdigit(input[i])) {
            string num;
            while (i < input.size() && isdigit(input[i])) num += input[i++];
            i--;
            tokens.push_back({TokenType::NUMBER, num});
        } else if (input[i] == '+' || input[i] == '-' || input[i] == '*' || input[i] == '/') {
            tokens.push_back({TokenType::OPERATOR, string(1, input[i])});
        }
    }
    tokens.push_back({TokenType::END, ""});
    return tokens;
}

int main() {
    auto tokens = tokenize("3 + 4 * 2");
    for (const auto& t : tokens)
        cout << (t.type == TokenType::NUMBER ? "NUMBER" : t.type == TokenType::OPERATOR ? "OPERATOR" : "END") << ": " << t.value << endl;
    return 0;
}
